export function identifyCSV(text){const header=text.replace(/^\uFEFF/,'').split(/\r?\n/)[0].split(',').map(s=>s.trim().replace(/^"|"$/g,''));const id=header[1];if(header.length!==2||!['observation_date','DATE','date'].includes(header[0])||!['WPU08','WPU101','WPU133'].includes(id))throw Error('Use a FRED CSV with an observation_date and WPU08, WPU101, or WPU133 column.');if(parseCSV(text).rows.length<13)throw Error(id+': at least 13 valid monthly observations are required.');return id}
export function parseCSV(text){
 const map=new Map();let dropped=0,duplicates=0;
 for(const line of text.trim().split(/\r?\n/).slice(1)){const [date,raw]=line.split(',');const value=Number(raw);if(!/^\d{4}-(0[1-9]|1[0-2])-01$/.test(date)||!raw?.trim()||!Number.isFinite(value)||value<=0){dropped++;continue}const month=date.slice(0,7);if(map.has(month))duplicates++;map.set(month,{date:month,value});}
 return {rows:[...map.values()].sort((a,b)=>a.date.localeCompare(b.date)),dropped,duplicates};
}
export function shiftMonth(date,delta){const [y,m]=date.split('-').map(Number);const d=new Date(Date.UTC(y,m-1+delta,1));return d.toISOString().slice(0,7)}
export function derive(rows){const map=new Map(rows.map(r=>[r.date,r.value]));const changes=new Map(rows.map(r=>{const p=map.get(shiftMonth(r.date,-1));return [r.date,p?100*(r.value/p-1):null]}));return rows.map(r=>{const prev=map.get(shiftMonth(r.date,-12));const window=Array.from({length:12},(_,i)=>changes.get(shiftMonth(r.date,-i)));let vol=null;if(window.every(v=>v!=null)){const mean=window.reduce((a,b)=>a+b,0)/12;vol=Math.sqrt(window.reduce((s,v)=>s+(v-mean)**2,0)/11)}return {...r,index:r.value,mom:changes.get(r.date),yoy:prev?100*(r.value/prev-1):null,vol}})}
export function completeMonths(rows){if(!rows.length)return [];const map=new Map(rows.map(r=>[r.date,r]));const result=[];for(let d=rows[0].date;d<=rows.at(-1).date;d=shiftMonth(d,1))result.push(map.get(d)||{date:d,index:null,mom:null,yoy:null,vol:null});return result;}
export function monthDistance(from,to){const [fy,fm]=from.split('-').map(Number),[ty,tm]=to.split('-').map(Number);return (ty-fy)*12+tm-fm}
export function sampleDeviation(values){if(values.length<2||values.some(v=>v==null||!Number.isFinite(v)))return null;const mean=values.reduce((a,b)=>a+b,0)/values.length;return Math.sqrt(values.reduce((sum,v)=>sum+(v-mean)**2,0)/(values.length-1))}
export function analyzeRange(history,from,to){const months=monthDistance(from,to)+1,windowMonths=Math.min(12,months);if(months<1)throw Error('Invalid date range');const map=new Map(history.map(r=>[r.date,r]));const selected=history.filter(r=>r.date>=from&&r.date<=to);const rows=selected.map(r=>{const reference=map.get(shiftMonth(r.date,-windowMonths))?.index;const returns=Array.from({length:windowMonths},(_,i)=>map.get(shiftMonth(r.date,-i))?.mom??null);return {...r,yoy:r.index!=null&&reference!=null?100*(r.index/reference-1):null,vol:sampleDeviation(returns)}});const valid=rows.filter(r=>r.index!=null),first=valid[0],last=valid.at(-1);const average=key=>{const values=rows.map(r=>r[key]).filter(v=>v!=null);return {value:values.length?values.reduce((a,b)=>a+b,0)/values.length:null,count:values.length}};const complete=rows.length===months&&rows.every(r=>r.index!=null&&r.mom!=null);return {rows,months,windowMonths,first,last,rangeChange:months>1&&first?.date===from&&last?.date===to?100*(last.index/first.index-1):null,monthly:average('mom'),comparison:average('yoy'),rangeVolatility:complete?sampleDeviation(rows.map(r=>r.mom)):null,returnCount:rows.filter(r=>r.mom!=null).length}}
